-- Existing databases: apply atomically; do not rerun fresh init.
BEGIN;
CREATE TABLE IF NOT EXISTS game_wing_progression_rules (
 version INTEGER PRIMARY KEY CHECK(version>0),
 active BOOLEAN NOT NULL DEFAULT FALSE,
 configuration JSONB NOT NULL CHECK(jsonb_typeof(configuration)='object')
);
CREATE UNIQUE INDEX IF NOT EXISTS game_wing_progression_one_active ON game_wing_progression_rules((active)) WHERE active;
CREATE TABLE IF NOT EXISTS game_wing_transform_edges (
 source_item INTEGER NOT NULL REFERENCES game_equipment(id),
 target_item INTEGER NOT NULL REFERENCES game_equipment(id),
 operation TEXT NOT NULL CHECK(operation IN ('wing.upgrade','wing.change')),
 PRIMARY KEY(source_item,target_item,operation), CHECK(source_item<>target_item)
);
CREATE TABLE IF NOT EXISTS equipment_wing_power_state (
 uid BIGINT PRIMARY KEY REFERENCES item_instances(uid) ON DELETE CASCADE,
 state JSONB NOT NULL CHECK(jsonb_typeof(state)='array' AND jsonb_array_length(state)=3)
);
ALTER TABLE game_rift_rule_versions ADD COLUMN IF NOT EXISTS wing_rewards JSONB;
