BEGIN
 IF EXISTS(SELECT FROM game_wing_progression_rules WHERE active AND version<>1) THEN RAISE EXCEPTION 'another wing configuration is active'; END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements(cfg->'Items') w WHERE NOT EXISTS(SELECT FROM game_equipment e WHERE e.id=(w->>'Item')::integer)) THEN RAISE EXCEPTION 'native wing template missing'; END IF;
 IF EXISTS(SELECT FROM game_wing_progression_rules WHERE version=1 AND configuration IS DISTINCT FROM cfg) THEN RAISE EXCEPTION 'wing configuration1 is occupied'; END IF;
 INSERT INTO game_wing_progression_rules(version,active,configuration) VALUES(1,true,cfg) ON CONFLICT(version) DO UPDATE SET active=true WHERE game_wing_progression_rules.configuration=EXCLUDED.configuration;
 INSERT INTO game_wing_transform_edges(source_item,target_item,operation)
 SELECT (v->>'Source')::integer,(v->>'Target')::integer,v->>'Operation'
 FROM jsonb_array_elements(cfg->'Recipes') v WHERE v->>'Operation' IN ('wing.upgrade','wing.change') ON CONFLICT DO NOTHING;
END $wing_config$;

DO $rift_wing_rewards$
DECLARE active_version INTEGER; base_version INTEGER; original JSONB; revised JSONB; rewards JSONB;
BEGIN
 SELECT version INTO active_version FROM game_rift_rule_active WHERE id=1 FOR UPDATE;
 IF active_version NOT IN (12,13,14) OR active_version IS NULL THEN RAISE EXCEPTION 'wing rewards require current rift12/13 or idempotent rift14'; END IF;
 SELECT max(version) INTO base_version FROM game_rift_rule_versions WHERE version IN (12,13) AND published;
 SELECT to_jsonb(r) INTO original FROM game_rift_rule_versions r WHERE version=base_version AND published AND cumulative_legendary_per_tier=10 AND normal_boss_equipment=10;
 IF original IS NULL OR (SELECT count(*) FROM game_rift_class_rules WHERE version=base_version)<>4 OR (SELECT count(*) FROM game_rift_ability_rules WHERE version=base_version)<>3 THEN RAISE EXCEPTION 'wing rewards require complete unchanged predecessor'; END IF;
 rewards := '{"Milestones":[{"Tier":10,"Materials":[{"ItemID":25028,"Count":4}]},{"Tier":30,"Materials":[{"ItemID":25029,"Count":2},{"ItemID":25028,"Count":2}]},{"Tier":50,"Materials":[{"ItemID":25029,"Count":6},{"ItemID":25028,"Count":2}]},{"Tier":70,"Materials":[{"ItemID":25029,"Count":16}]},{"Tier":90,"Materials":[{"ItemID":25029,"Count":32}]},{"Tier":110,"Materials":[{"ItemID":25029,"Count":60}]},{"Tier":130,"Materials":[{"ItemID":25029,"Count":100}]},{"Tier":150,"Materials":[{"ItemID":25029,"Count":160}]}],"RepeatBands":[{"MinTier":1,"Materials":[{"ItemID":25027,"Count":1}]},{"MinTier":10,"Materials":[{"ItemID":25027,"Count":2}]},{"MinTier":20,"Materials":[{"ItemID":25027,"Count":3}]},{"MinTier":30,"Materials":[{"ItemID":25027,"Count":4}]},{"MinTier":40,"Materials":[{"ItemID":25028,"Count":1}]},{"MinTier":50,"Materials":[{"ItemID":25028,"Count":1},{"ItemID":25027,"Count":1}]},{"MinTier":60,"Materials":[{"ItemID":25028,"Count":1},{"ItemID":25027,"Count":2}]},{"MinTier":70,"Materials":[{"ItemID":25028,"Count":1},{"ItemID":25027,"Count":3}]},{"MinTier":80,"Materials":[{"ItemID":25028,"Count":1},{"ItemID":25027,"Count":4}]},{"MinTier":90,"Materials":[{"ItemID":25028,"Count":2}]},{"MinTier":100,"Materials":[{"ItemID":25028,"Count":2},{"ItemID":25027,"Count":1}]},{"MinTier":110,"Materials":[{"ItemID":25028,"Count":2},{"ItemID":25027,"Count":2}]},{"MinTier":120,"Materials":[{"ItemID":25028,"Count":2},{"ItemID":25027,"Count":3}]},{"MinTier":130,"Materials":[{"ItemID":25028,"Count":2},{"ItemID":25027,"Count":4}]},{"MinTier":140,"Materials":[{"ItemID":25028,"Count":3}]},{"MinTier":150,"Materials":[{"ItemID":25028,"Count":3},{"ItemID":25027,"Count":1}]}],"RareFeather":{"Item":11682,"Count":1,"ChanceBP":50}}'::jsonb;
 revised := original || jsonb_build_object('version',14,'published',false,'wing_rewards',rewards);
 IF NOT EXISTS(SELECT FROM game_rift_rule_versions WHERE version=14) THEN
  INSERT INTO game_rift_rule_versions SELECT (jsonb_populate_record(NULL::game_rift_rule_versions,revised)).*;
  INSERT INTO game_rift_class_rules SELECT 14,class,hp_bp,damage_bp FROM game_rift_class_rules WHERE version=base_version;
  INSERT INTO game_rift_ability_rules SELECT 14,id,name,affix,warning,shape,radius,inner_radius,length,delay_ms,damage_pct FROM game_rift_ability_rules WHERE version=base_version;
  UPDATE game_rift_rule_versions SET published=true WHERE version=14;
 ELSIF (SELECT to_jsonb(r) FROM game_rift_rule_versions r WHERE version=14) IS DISTINCT FROM (revised || '{"published":true}'::jsonb) THEN
  RAISE EXCEPTION 'rift14 already contains a different configuration';
 END IF;
 UPDATE game_rift_rule_active SET version=14 WHERE id=1 AND version IN (12,13);
END $rift_wing_rewards$;
DO $wing_guide$
DECLARE quest CONSTANT INTEGER := 1900030002;
BEGIN
 IF NOT EXISTS(SELECT FROM game_wing_progression_rules WHERE active) THEN RAISE EXCEPTION 'wing guide requires active cube wing rules'; END IF;
 IF EXISTS(SELECT FROM map_npcs WHERE map_file='qw0007' AND npc_id=96 AND (name<>'幻翼域使者' OR script<>'N2619LC' OR sprite<>2619 OR x<>9686 OR y<>5510 OR hide)) THEN RAISE EXCEPTION 'wing NPC placement ID96 is occupied'; END IF;
 IF EXISTS(SELECT FROM map_npcs WHERE map_file='qw0007' AND (name='幻翼域使者' OR script='N2619LC') AND npc_id<>96) THEN RAISE EXCEPTION 'wing NPC already exists with another identity'; END IF;
 IF NOT EXISTS(SELECT FROM map_npcs WHERE map_file='qw0007' AND npc_id=73 AND name='巧匠左慈' AND script='N611FY') OR NOT EXISTS(SELECT FROM game_tasks WHERE id=1900030001 AND name='问鼎周天') OR NOT EXISTS(SELECT FROM game_equipment WHERE id=20609 AND name='光之翼') THEN RAISE EXCEPTION 'wing guide requires original artisan, cube quest and starter'; END IF;
 IF EXISTS(SELECT FROM game_tasks WHERE id=quest AND name<>'幻翼初展') THEN RAISE EXCEPTION 'wing guide quest identity collision'; END IF;
 INSERT INTO map_npcs(map_file,npc_id,sprite,name,script,x,y,dir,sell_list,trans_list,hide)
 VALUES('qw0007',96,2619,'幻翼域使者','N2619LC',9686,5510,67,0,0,FALSE) ON CONFLICT DO NOTHING;
 INSERT INTO game_tasks(id,name,npc,map,level_min,level_max,descr,reward)
 VALUES(quest,'幻翼初展','巧匠左慈','龙城',0,0,'周天鼎既已修复，也该让你识一识羽翼之道。去见龙城的幻翼域使者，他会赠你一副光之翼；今后升阶、换系和融入威能，皆可用周天鼎完成。','永久绑定的光之翼一副') ON CONFLICT DO NOTHING;
 INSERT INTO game_task_prerequisites(task_id,seq,prerequisite_task_id) VALUES(quest,1,1900030001) ON CONFLICT DO NOTHING;
 INSERT INTO game_task_rewards(task_id) VALUES(quest) ON CONFLICT DO NOTHING;
 INSERT INTO game_task_reward_items(task_id,seq,item_id,qty) VALUES(quest,1,20609,1) ON CONFLICT DO NOTHING;
 INSERT INTO game_task_flows(layer,task_id,task_name,publisher) VALUES('base',quest,'幻翼初展','巧匠左慈') ON CONFLICT DO NOTHING;
 INSERT INTO game_task_flow_steps(layer,task_id,step_no,target_npc,kind,text,say,done)
 VALUES('base',quest,1,'幻翼域使者','talk','前往龙城，与幻翼域使者交谈，领取光之翼。','这副光之翼先交你。洞天首通与反复历练皆能积羽，升阶、换系和融入威能都用周天鼎。',TRUE) ON CONFLICT DO NOTHING;
END $wing_guide$;
COMMIT;
